import csv
import io
import re


def parse_csv(raw_csv: str):
    expected_width = 24
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    records = list(csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
    ))

    first = next(
        (i for i, row in enumerate(records) if any(cell.strip() for cell in row)),
        None,
    )
    if first is None:
        return {
            "columns": ["column_" + str(i + 1) for i in range(expected_width)],
            "rows": [[""] * expected_width for _ in records],
        }

    def looks_like_header(row):
        if len(row) != expected_width:
            return False
        names = [cell.strip() for cell in row]
        return (
            len(set(names)) == expected_width
            and all(re.fullmatch(r"[A-Za-z_][A-Za-z_0-9]*", name) for name in names)
        )

    header_index = first
    if len(records[first]) < expected_width:
        for i in range(first + 1, len(records)):
            if looks_like_header(records[i]):
                header_index = i
                break
            if len(records[i]) >= expected_width:
                break

    columns = records[header_index][:]
    rows = records[header_index + 1:]
    width = max(expected_width, len(columns), max(map(len, rows), default=0))

    # Retain surplus fields rather than guessing where a delimiter was unintended.
    used_names = set(columns)
    for i in range(len(columns), width):
        name = "column_" + str(i + 1)
        while name in used_names:
            name += "_"
        columns.append(name)
        used_names.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
